  equation and solving for C gives the answer, C = p*(1000+Q)/(1-p)
  where Q sums e(.) over the six hundreds/tens/units entry states.

  Cross-checked against independent Monte Carlo simulation of the
  literal generation-and-validation process (~319.3, matching). }

CONST
  pLetter = 0.14;
  pHash = 0.02;

VAR
  eu1, eu2, eu3, eu4, eu5, eu6, eu7, eu8, eu9: REAL;
  et1, et2, et3, et4, et5, et6, et7, et8, et9: REAL;
  eh1, eh2, eh3, eh4, eh5, eh6, eh7, eh8, eh9: REAL;
  lowerETens, lowerEHundreds: REAL;
  q, answer: REAL;

FUNCTION SolveState(v: REAL; withinSum: REAL; kWithin: INTEGER;
                     lowerESum: REAL; nLower: INTEGER): REAL;
VAR
  k: INTEGER;
  r, lowerAdj: REAL;
BEGIN
  k := kWithin + nLower;
  r := pHash + pLetter * k;
  lowerAdj := nLower * v + lowerESum;
  SolveState := (pHash * v + pLetter * withinSum + pLetter * lowerAdj) / r
END;

BEGIN
  { Units group: placevalue 1, no lower group (nLower = 0). }
  eu3 := SolveState(3, 0, 0, 0, 0);
  eu4 := SolveState(4, 0, 0, 0, 0);
  eu8 := SolveState(8, 0, 0, 0, 0);
  eu9 := SolveState(9, 0, 0, 0, 0);
  eu2 := SolveState(2, eu3, 1, 0, 0);
  eu7 := SolveState(7, eu8, 1, 0, 0);
  eu6 := SolveState(6, eu7, 1, 0, 0);
  eu5 := SolveState(5, eu6, 1, 0, 0);
  eu1 := SolveState(1, eu2 + eu4 + eu9, 3, 0, 0);

  { Tens group: placevalue 10, lower group = units (entries I, V). }
  lowerETens := eu1 + eu5;
  et3 := SolveState(30, 0, 0, lowerETens, 2);
  et4 := SolveState(40, 0, 0, lowerETens, 2);
  et8 := SolveState(80, 0, 0, lowerETens, 2);
  et9 := SolveState(90, 0, 0, lowerETens, 2);
  et2 := SolveState(20, et3, 1, lowerETens, 2);
  et7 := SolveState(70, et8, 1, lowerETens, 2);
  et6 := SolveState(60, et7, 1, lowerETens, 2);
  et5 := SolveState(50, et6, 1, lowerETens, 2);
  et1 := SolveState(10, et2 + et4 + et9, 3, lowerETens, 2);

  { Hundreds group: placevalue 100, lower groups = tens + units. }
  lowerEHundreds := et1 + et5 + eu1 + eu5;
  eh3 := SolveState(300, 0, 0, lowerEHundreds, 4);
  eh4 := SolveState(400, 0, 0, lowerEHundreds, 4);
  eh8 := SolveState(800, 0, 0, lowerEHundreds, 4);
  eh9 := SolveState(900, 0, 0, lowerEHundreds, 4);
  eh2 := SolveState(200, eh3, 1, lowerEHundreds, 4);
  eh7 := SolveState(700, eh8, 1, lowerEHundreds, 4);
  eh6 := SolveState(600, eh7, 1, lowerEHundreds, 4);
  eh5 := SolveState(500, eh6, 1, lowerEHundreds, 4);
  eh1 := SolveState(100, eh2 + eh4 + eh9, 3, lowerEHundreds, 4);

  { Thousands closed form (see comment above). }
  q := eh1 + eh5 + et1 + et5 + eu1 + eu5;
  answer := pLetter * (1000 + q) / (1 - pLetter);

  WRITELN(answer:0:8)
END.
